-- RedGuardian schema v1 (mysql). Generated by scripts/export_schema.py; do not edit.

CREATE TABLE documents (
	corpus_id VARCHAR(64) NOT NULL, 
	doc_id VARCHAR(64) NOT NULL, 
	title VARCHAR(256), 
	source VARCHAR(256) NOT NULL, 
	trust VARCHAR(16) NOT NULL, 
	poisoned BOOL NOT NULL, 
	attack_id VARCHAR(32), 
	sha256 VARCHAR(64) NOT NULL, 
	text TEXT NOT NULL, 
	PRIMARY KEY (corpus_id, doc_id)
);

CREATE TABLE experiments (
	experiment_id VARCHAR(36) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	objective TEXT, 
	config JSON NOT NULL, 
	created_at DATETIME(6) NOT NULL, 
	PRIMARY KEY (experiment_id)
);

CREATE TABLE memory_entries (
	memory_id VARCHAR(36) NOT NULL, 
	namespace VARCHAR(64) NOT NULL, 
	content TEXT NOT NULL, 
	source_type VARCHAR(16) NOT NULL, 
	source_id VARCHAR(128) NOT NULL, 
	trust VARCHAR(16) NOT NULL, 
	run_id VARCHAR(36), 
	session_id VARCHAR(64), 
	contains_canary BOOL NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	created_at DATETIME(6) NOT NULL, 
	PRIMARY KEY (memory_id)
);

CREATE INDEX ix_memory_entries_namespace ON memory_entries (namespace);

CREATE TABLE schema_info (
	version INTEGER NOT NULL AUTO_INCREMENT, 
	applied_at DATETIME(6) NOT NULL, 
	PRIMARY KEY (version)
);

CREATE TABLE metric_results (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	experiment_id VARCHAR(36) NOT NULL, 
	scope VARCHAR(128) NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	numerator INTEGER NOT NULL, 
	denominator INTEGER NOT NULL, 
	value FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(experiment_id) REFERENCES experiments (experiment_id)
);

CREATE TABLE runs (
	run_id VARCHAR(36) NOT NULL, 
	experiment_id VARCHAR(36), 
	kind VARCHAR(16) NOT NULL, 
	attack_id VARCHAR(32) NOT NULL, 
	attack_version VARCHAR(32) NOT NULL, 
	attack_sha256 VARCHAR(64) NOT NULL, 
	adapter VARCHAR(64) NOT NULL, 
	model VARCHAR(128), 
	model_params JSON NOT NULL, 
	defense_profile VARCHAR(64) NOT NULL, 
	defense_config JSON NOT NULL, 
	seed INTEGER, 
	corpus_state_id VARCHAR(64), 
	memory_state_id VARCHAR(64), 
	status VARCHAR(16) NOT NULL, 
	error TEXT, 
	started_at DATETIME(6) NOT NULL, 
	finished_at DATETIME(6), 
	PRIMARY KEY (run_id), 
	FOREIGN KEY(experiment_id) REFERENCES experiments (experiment_id)
);

CREATE INDEX ix_runs_attack_id ON runs (attack_id);

CREATE INDEX ix_runs_defense_profile ON runs (defense_profile);

CREATE TABLE evaluations (
	run_id VARCHAR(36) NOT NULL, 
	evaluator_version VARCHAR(32) NOT NULL, 
	result JSON NOT NULL, 
	evaluated_at DATETIME(6) NOT NULL, 
	PRIMARY KEY (run_id, evaluator_version), 
	FOREIGN KEY(run_id) REFERENCES runs (run_id)
);

CREATE TABLE events (
	event_id VARCHAR(36) NOT NULL, 
	run_id VARCHAR(36) NOT NULL, 
	seq INTEGER NOT NULL, 
	timestamp DATETIME(6) NOT NULL, 
	event_type VARCHAR(32) NOT NULL, 
	attack_id VARCHAR(32), 
	stage INTEGER, 
	source_type VARCHAR(16), 
	source_id VARCHAR(128), 
	destination VARCHAR(128), 
	canary_id VARCHAR(64), 
	decision VARCHAR(16), 
	defense_id VARCHAR(64), 
	reason TEXT, 
	payload JSON NOT NULL, 
	PRIMARY KEY (event_id), 
	UNIQUE (run_id, seq), 
	FOREIGN KEY(run_id) REFERENCES runs (run_id)
);

CREATE INDEX ix_events_event_type ON events (event_type);

INSERT INTO schema_info (version, applied_at) VALUES (1, UTC_TIMESTAMP(6));
